public object Wire {
    public fun requireBasicParameter(value: Any?, name: String) { if (value != null) throw ApiException("Unsupported Kotlin parameter serialization: " + name) }
    private fun bounded(value: String): String { require(value.length <= 65536) { "Parameter exceeds the Kotlin scalar limit" }; return value }
    public fun encodePath(value: String): String = java.net.URLEncoder.encode(bounded(value), Charsets.UTF_8).replace("+", "%20")
    public fun scalar(value: Any?): String = bounded(when (value) { is String -> value; is Number, is Boolean -> value.toString(); is WireEnum -> value.wireValue(); else -> throw ApiException("Kotlin parameters require scalar values") })
    public fun query(name: String, value: Any?, style: String = "form", explode: Boolean = true, allowReserved: Boolean = false): String = queryPairs(name, value, style, explode).joinToString("&") { encodeComponent(bounded(it.first), false) + "=" + encodeComponent(it.second, allowReserved) }
    public fun joinQuery(values: List<String>): String { val present = values.filter { it.isNotEmpty() }; return if (present.isEmpty()) "" else "?" + present.joinToString("&") }
    public fun json(value: Any?): String = Json.stringify(value)

    private val whitespace = Regex("\\s+")

    internal fun readBounded(stream: java.io.InputStream, maximumBytes: Int, status: Int): String = stream.use { input ->
        val output = java.io.ByteArrayOutputStream()
        val buffer = ByteArray(8192)
        while (true) {
            val count = input.read(buffer)
            if (count < 0) break
            if (output.size().toLong() + count > maximumBytes) throw ApiResponseTooLargeException(maximumBytes, status)
            output.write(buffer, 0, count)
        }
        String(output.toByteArray(), Charsets.UTF_8)
    }

    internal fun transportFailure(error: Throwable): ApiException {
        val cause = if (error is java.util.concurrent.CompletionException) error.cause ?: error else error
        return when (cause) {
            is ApiException -> cause
            is java.io.IOException -> ioFailure(cause)
            else -> ApiException("Request failed: " + cause, null, cause)
        }
    }

    internal fun ioFailure(error: java.io.IOException): ApiTransportException = if (error is java.net.http.HttpTimeoutException) ApiTimeoutException("Request timed out", error) else ApiTransportException("Transport failure", error)

    internal fun headerMap(headers: Map<String, List<String>>): Map<String, List<String>> {
        val result = java.util.TreeMap<String, List<String>>(String.CASE_INSENSITIVE_ORDER)
        for (entry in headers.entries) {
            // A Java header map may carry a null key (the HTTP status line).
            val key: String? = entry.key
            if (key == null) continue
            result[key] = (result[key] ?: emptyList()) + entry.value
        }
        return java.util.Collections.unmodifiableMap(result)
    }

    internal fun requestId(headers: Map<String, List<String>>): String? = headers["x-request-id"]?.firstOrNull()?.takeIf { it.isNotEmpty() } ?: headers["request-id"]?.firstOrNull()?.takeIf { it.isNotEmpty() }

    internal fun decodeErrorBody(rawBody: String): Pair<Any?, Boolean> = if (rawBody.isBlank()) Pair(null, false) else try {
        Pair(Json.parse(rawBody), true)
    } catch (error: Exception) {
        Pair(rawBody, false)
    }

    internal fun errorBody(rawBody: String): Any? = decodeErrorBody(rawBody).first

    internal fun errorText(body: Any?): String? {
        val sources = mutableListOf<Map<*, *>>()
        if (body is Map<*, *>) {
            val inner = body["error"]
            if (inner is String) return boundedText(inner)
            if (inner is Map<*, *>) sources.add(inner)
            sources.add(body)
        } else if (body is String) {
            return boundedText(body)
        }
        for (source in sources) {
            for (key in listOf("message", "detail", "title", "error_description")) {
                val value = source[key]
                if (value is String) boundedText(value)?.let { return it }
            }
        }
        return null
    }

    private fun boundedText(value: String): String? {
        val text = value.split(whitespace).filter { it.isNotEmpty() }.joinToString(" ")
        if (text.isEmpty()) return null
        return if (text.length <= 500) text else text.substring(0, 497) + "..."
    }

    private val decimalNumber = Regex("[0-9]+(?:\\.[0-9]+)?")
    private val wholeNumber = Regex("[0-9]+")
    private val rateLimitReset = Regex("(?:^|[;,\\s])t=([0-9]+)(?:[;,\\s]|$)")

    /** `x-should-retry: true|false` is the server's verdict; otherwise 408, 409, 429 and every 5xx. */
    internal fun shouldRetry(status: Int, headers: Map<String, List<String>>): Boolean = when (headerMap(headers)["x-should-retry"]?.firstOrNull()) {
        "true" -> true
        "false" -> false
        else -> status == 408 || status == 409 || status == 429 || status >= 500
    }

    /** The wait the server asked for, in milliseconds: `retry-after-ms`, then `Retry-After`, then the RateLimit reset. */
    internal fun serverRetryDelay(headers: Map<String, List<String>>, now: Long): Double? {
        val lookup = headerMap(headers)
        val milliseconds = (lookup["retry-after-ms"]?.firstOrNull() ?: "").trim()
        if (decimalNumber.matches(milliseconds)) return milliseconds.toDouble()
        val retryAfter = (lookup["retry-after"]?.firstOrNull() ?: "").trim()
        if (decimalNumber.matches(retryAfter)) return retryAfter.toDouble() * 1000.0
        if (retryAfter.isNotEmpty()) {
            val date = try {
                java.time.ZonedDateTime.parse(retryAfter, java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME).toInstant().toEpochMilli()
            } catch (error: java.time.format.DateTimeParseException) {
                null
            }
            if (date != null) return maxOf(0.0, (date - now).toDouble())
        }
        val reset = rateLimitReset.find(lookup["ratelimit"]?.firstOrNull() ?: "")?.groupValues?.get(1)
            ?: (lookup["ratelimit-reset"]?.firstOrNull() ?: "").trim().takeIf { wholeNumber.matches(it) }
        return reset?.toDouble()?.times(1000.0)
    }

    /**
     * Milliseconds to wait before the next attempt, or null when none should happen. A
     * server asking for longer than maxRetryDelay gets its error surfaced at once;
     * otherwise the wait is the server's own, else 500 ms x 2^attempt (at most 60 s and
     * maxRetryDelay) less a jitter of up to a quarter. retryBudget caps the whole call.
     */
    internal fun retryWait(attempt: Int, headers: Map<String, List<String>>?, elapsed: Long, random: Double, now: Long, options: ClientOptions): Long? {
        val maximum = options.maxRetryDelay.toMillis().toDouble()
        val server = if (headers == null) null else serverRetryDelay(headers, now)
        if (server != null && server > maximum) return null
        val wait = server ?: (minOf(maximum, 60000.0, 500.0 * Math.pow(2.0, attempt.toDouble())) * (1.0 - 0.25 * random.coerceIn(0.0, 1.0)))
        val budget = options.retryBudget
        if (budget != null && elapsed + wait > budget.toMillis()) return null
        return Math.ceil(wait).toLong()
    }

    /**
     * The request with its Idempotency-Key: the caller's, else the one the contract's
     * header parameter carries, else a fresh UUID for a POST the contract marks
     * idempotent or a client with autoIdempotencyKey, as the TypeScript lane mints it.
     */
    internal fun withIdempotencyKey(request: Request, explicit: String?, auto: Boolean): Request {
        val key = explicit?.takeIf { it.isNotEmpty() }
            ?: if (idempotencyKey(request.headers) == null && request.method == "POST" && (request.retryable || auto)) java.util.UUID.randomUUID().toString() else null
        if (key == null) return request
        return request.copy(headers = request.headers.filterKeys { !it.equals("Idempotency-Key", ignoreCase = true) } + ("Idempotency-Key" to key))
    }

    internal fun idempotencyKey(headers: Map<String, String>): String? = headers.entries.firstOrNull { it.key.equals("Idempotency-Key", ignoreCase = true) && it.value.isNotEmpty() }?.value

    internal suspend fun pause(millis: Long) {
        if (millis <= 0L) return
        delay(millis)
    }

    private const val HEX = "0123456789ABCDEF"
    private const val UNRESERVED = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"
    private const val RESERVED = ":/?#[]@!\$&'()*+,;="

    /**
     * Percent-encodes the UTF-8 bytes of [value]: every byte but the unreserved ones,
     * and the reserved ones too unless [allowReserved]; [plus] writes a space as `+`.
     */
    internal fun encodeComponent(value: String, allowReserved: Boolean, plus: Boolean = false): String = buildString {
        for (byte in value.toByteArray(Charsets.UTF_8)) {
            val code = byte.toInt() and 0xff
            val character = code.toChar()
            if (code < 0x80 && (character in UNRESERVED || (allowReserved && character in RESERVED))) append(character)
            else if (plus && character == ' ') append('+')
            else { append('%'); append(HEX[code shr 4]); append(HEX[code and 0x0f]) }
        }
    }

    /** A generated model travels as its JSON value; anything else as it is. */
    private fun modelValue(value: Any?): Any? = if (value is Json.Encodable) value.toJson() else value

    private fun items(value: Any): List<Any?>? = when (value) {
        is Iterable<*> -> value.toList()
        is Array<*> -> value.toList()
        else -> null
    }

    /**
     * The (name, value) pairs of one query parameter in the declared [style]: `form`
     * (one pair per item when [explode], else comma-joined), `spaceDelimited`,
     * `pipeDelimited` or `deepObject`, over scalars, lists, maps and generated models.
     * A null value or member is left out.
     */
    internal fun queryPairs(name: String, value: Any?, style: String, explode: Boolean): List<Pair<String, String>> {
        val shaped = modelValue(value) ?: return emptyList()
        val pairs = mutableListOf<Pair<String, String>>()
        val list = items(shaped)
        when {
            style == "deepObject" -> deepObject(pairs, name, shaped, "")
            style == "spaceDelimited" || style == "pipeDelimited" -> {
                val members = list ?: if (shaped is Map<*, *>) shaped.entries.filter { it.value != null }.flatMap { listOf(it.key, it.value) } else listOf(shaped)
                pairs.add(name to members.filterNotNull().joinToString(if (style == "spaceDelimited") " " else "|") { scalar(modelValue(it)) })
            }
            list != null -> {
                val present = list.filterNotNull().map { scalar(modelValue(it)) }
                if (explode) present.forEach { pairs.add(name to it) } else pairs.add(name to present.joinToString(","))
            }
            shaped is Map<*, *> -> {
                val entries = shaped.entries.filter { it.value != null }.map { it.key.toString() to scalar(modelValue(it.value)) }
                if (explode) pairs.addAll(entries) else pairs.add(name to entries.joinToString(",") { it.first + "," + it.second })
            }
            else -> pairs.add(name to scalar(shaped))
        }
        return pairs
    }

    private fun deepObject(pairs: MutableList<Pair<String, String>>, name: String, value: Any?, prefix: String) {
        val shaped = modelValue(value) ?: return
        val list = items(shaped)
        when {
            shaped is Map<*, *> -> shaped.forEach { (key, item) -> deepObject(pairs, name, item, prefix + "[" + key + "]") }
            list != null -> list.forEachIndexed { index, item -> deepObject(pairs, name, item, prefix + "[" + index + "]") }
            else -> pairs.add(name + prefix to scalar(shaped))
        }
    }

    /**
     * An application/x-www-form-urlencoded body from a map or a generated model: a
     * list repeats its key, a null is sent empty and a nested object as its JSON text.
     */
    public fun form(value: Any?): String {
        val fields = modelValue(value) as? Map<*, *> ?: throw ApiException("Form bodies require a map or a generated model")
        val parts = mutableListOf<String>()
        for ((key, item) in fields) {
            val name = encodeComponent(key.toString(), false, true) + "="
            val shaped = modelValue(item)
            val list = if (shaped == null) null else items(shaped)
            if (list != null) list.forEach { parts.add(name + formValue(it)) } else parts.add(name + formValue(shaped))
        }
        return parts.joinToString("&")
    }

    private fun formValue(value: Any?): String = encodeComponent(when (val shaped = modelValue(value)) {
        null -> ""
        is String -> shaped
        is Number, is Boolean -> shaped.toString()
        is WireEnum -> shaped.wireValue()
        else -> Json.stringify(shaped)
    }, false, true)

    /**
     * An application/octet-stream body: a ByteArray, an InputStream (read once, so a
     * retry resends the same bytes) or a String, sent as its UTF-8 bytes.
     */
    public fun binary(value: Any?): ByteArray = when (value) {
        is ByteArray -> value
        is java.io.InputStream -> value.use { it.readBytes() }
        is String -> value.toByteArray(Charsets.UTF_8)
        else -> throw ApiException("Binary bodies require a ByteArray, an InputStream or a String")
    }

    /** Bounded wire bytes, including MIME framing. Input streams are closed after reading. */
    public fun multipart(value: Any?, binaryFields: Set<String>, repeatFields: Set<String>, contentTypes: Map<String, String>, maxBytes: Int, checkCancellation: () -> Unit): MultipartEncoded {
        require(maxBytes in 1..67108864) { "maxUploadBytes must be from 1 byte through 64 MiB" }
        checkCancellation()
        val fields = modelValue(value) as? Map<*, *> ?: throw ApiException("Multipart bodies require a map or generated upload body")
        val boundary = "omniwrap-" + java.util.UUID.randomUUID().toString()
        val output = java.io.ByteArrayOutputStream(minOf(maxBytes, 8192))
        fun append(bytes: ByteArray, offset: Int = 0, length: Int = bytes.size) {
            checkCancellation()
            if (length > maxBytes - output.size()) throw ApiException("Multipart upload exceeds maxUploadBytes")
            output.write(bytes, offset, length)
        }
        fun text(value: String) = append(value.toByteArray(Charsets.UTF_8))
        fun quoted(value: String): String {
            if (value.any { it.code < 32 || it.code == 127 }) throw ApiException("Multipart names and filenames cannot contain control characters")
            return value.replace("\\", "\\\\").replace("\"", "\\\"")
        }
        fun copy(stream: java.io.InputStream) {
            stream.use {
                val buffer = ByteArray(minOf(maxBytes, 8192))
                while (true) {
                    checkCancellation()
                    val count = it.read(buffer, 0, minOf(buffer.size, maxBytes - output.size() + 1))
                    if (count < 0) break
                    if (count == 0) {
                        val next = it.read()
                        if (next < 0) break
                        append(byteArrayOf(next.toByte()))
                    } else append(buffer, 0, count)
                }
            }
        }
        for ((key, value) in fields) {
            val name = key as? String ?: throw ApiException("Multipart field names must be strings")
            if (value == null) continue
            val repeated = if (name in repeatFields) value as? Iterable<*> ?: throw ApiException("Repeated multipart fields require an iterable") else listOf(value)
            for (entry in repeated) {
                checkCancellation()
                if (entry == null) continue
                val part = entry as? MultipartPart
                val source = part?.source ?: entry
                val binary = name in binaryFields || source is ByteArray || source is java.nio.file.Path || source is java.io.InputStream
                val filename = part?.filename ?: if (source is java.nio.file.Path) source.fileName.toString() else if (binary) "blob" else null
                val contentType = part?.contentType ?: contentTypes[name] ?: if (binary) "application/octet-stream" else if (modelValue(source) is Map<*, *> || modelValue(source) is List<*>) "application/json" else "text/plain"
                if (!Regex("[A-Za-z0-9!#$&^_.+*-]+/[A-Za-z0-9!#$&^_.+*-]+(?:;[^\\r\\n]*)?").matches(contentType) || contentType.any { it.code < 32 || it.code == 127 }) throw ApiException("Invalid multipart content type")
                text("--$boundary\r\nContent-Disposition: form-data; name=\"${quoted(name)}\"")
                if (filename != null) text("; filename=\"${quoted(filename)}\"")
                text("\r\nContent-Type: $contentType\r\n\r\n")
                if (binary) {
                    when (source) {
                        is ByteArray -> append(source)
                        is java.nio.file.Path -> copy(java.nio.file.Files.newInputStream(source))
                        is java.io.InputStream -> copy(source)
                        is Iterable<*> -> for (chunk in source) {
                            checkCancellation()
                            append(chunk as? ByteArray ?: throw ApiException("Multipart chunks must be ByteArray values"))
                        }
                        else -> throw ApiException("Binary multipart fields require bytes, a Path, an InputStream or byte chunks")
                    }
                } else {
                    val shaped = modelValue(source)
                    text(when (shaped) {
                        is String -> shaped
                        is Number, is Boolean -> shaped.toString()
                        is WireEnum -> shaped.wireValue()
                        is Map<*, *>, is List<*> -> Json.stringify(shaped)
                        else -> throw ApiException("Unsupported multipart field value")
                    })
                }
                text("\r\n")
            }
        }
        text("--$boundary--\r\n")
        checkCancellation()
        return MultipartEncoded(output.toByteArray(), "multipart/form-data; boundary=$boundary")
    }

}

public object Json {
    /** A generated model: [toJson] is its JSON value, so it can be sent as a request body. */
    public interface Encodable { public fun toJson(): Any? }
    public fun parse(source: String): Any? = Parser(source).parse()
    public fun stringify(value: Any?): String = encode(value, 0)
    private fun quote(value: String): String = buildString {
        append('"')
        for (character in value) {
            when (character) {
                '"' -> append("\\\"")
                '\\' -> append("\\\\")
                '\b' -> append("\\b")
                '\u000c' -> append("\\f")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> if (character.code < 0x20) {
                    append("\\u")
                    append(character.code.toString(16).padStart(4, '0'))
                } else append(character)
            }
        }
        append('"')
    }
    private fun encode(value: Any?, depth: Int): String {
        require(depth <= 128) { "JSON nesting exceeds the Kotlin codec limit" }
        return when (value) {
            null -> "null"
            is String -> quote(value)
            is Boolean -> value.toString()
            is Number -> {
                require(value.toDouble().isFinite()) { "JSON number must be finite" }
                value.toString()
            }
            is WireEnum -> quote(value.wireValue())
            is Encodable -> encode(value.toJson(), depth + 1)
            is Map<*, *> -> value.entries.joinToString(prefix = "{", postfix = "}") {
                val key = it.key as? String ?: throw ApiException("JSON object keys must be strings")
                quote(key) + ":" + encode(it.value, depth + 1)
            }
            is Iterable<*> -> value.joinToString(prefix = "[", postfix = "]") { encode(it, depth + 1) }
            is Array<*> -> value.joinToString(prefix = "[", postfix = "]") { encode(it, depth + 1) }
            else -> throw ApiException("Kotlin JSON bodies require maps, arrays, scalar values or generated models")
        }
    }
    private class Parser(private val text: String) {
        private var index = 0
        fun parse(): Any? {
            val result = value(0)
            skip()
            require(index == text.length) { "Trailing JSON data" }
            return result
        }
        private fun value(depth: Int): Any? {
            require(depth <= 128) { "JSON nesting exceeds the Kotlin codec limit" }
            skip()
            return when (text.getOrNull(index)) {
                'n' -> literal("null", null)
                't' -> literal("true", true)
                'f' -> literal("false", false)
                '"' -> string()
                '[' -> array(depth + 1)
                '{' -> objectValue(depth + 1)
                else -> number()
            }
        }
        private fun literal(word: String, result: Any?): Any? { expect(word); return result }
        private fun string(): String {
            expect("\"")
            val result = StringBuilder()
            while (index < text.length) {
                val character = text[index++]
                when (character) {
                    '"' -> return result.toString()
                    '\\' -> {
                        require(index < text.length) { "Unterminated JSON escape" }
                        val escaped = text[index++]
                        result.append(when (escaped) {
                            '"', '\\', '/' -> escaped
                            'b' -> '\b'
                            'f' -> '\u000c'
                            'n' -> '\n'
                            'r' -> '\r'
                            't' -> '\t'
                            'u' -> {
                                require(index + 4 <= text.length) { "Incomplete JSON Unicode escape" }
                                val digits = text.substring(index, index + 4)
                                require(digits.all { it in '0'..'9' || it in 'a'..'f' || it in 'A'..'F' }) { "Invalid JSON Unicode escape" }
                                index += 4
                                digits.toInt(16).toChar()
                            }
                            else -> throw ApiException("Invalid JSON string escape")
                        })
                    }
                    else -> {
                        require(character.code >= 0x20) { "Unescaped JSON control character" }
                        result.append(character)
                    }
                }
            }
            throw ApiException("Unterminated JSON string")
        }
        private fun array(depth: Int): List<Any?> {
            expect("["); skip()
            val result = mutableListOf<Any?>()
            if (peek(']')) { index++; return result }
            while (true) {
                result += value(depth); skip()
                if (peek(']')) { index++; return result }
                expect(",")
            }
        }
        private fun objectValue(depth: Int): Map<String, Any?> {
            expect("{"); skip()
            val result = linkedMapOf<String, Any?>()
            if (peek('}')) { index++; return result }
            while (true) {
                skip(); val key = string(); skip(); expect(":")
                require(!result.containsKey(key)) { "Duplicate JSON object key" }
                result[key] = value(depth); skip()
                if (peek('}')) { index++; return result }
                expect(",")
            }
        }
        private fun number(): Number {
            val start = index
            while (index < text.length && text[index] !in ",]} \t\r\n") index++
            val raw = text.substring(start, index)
            require(Regex("-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?").matches(raw)) { "Invalid JSON number" }
            if (!raw.contains('.') && !raw.contains('e', true)) {
                return raw.toLongOrNull() ?: throw ApiException("JSON integer exceeds Kotlin Long")
            }
            val result = raw.toDouble()
            require(result.isFinite()) { "JSON number must be finite" }
            return result
        }
        private fun expect(value: String) {
            require(text.startsWith(value, index)) { "Invalid JSON" }
            index += value.length
        }
        private fun peek(value: Char): Boolean = text.getOrNull(index) == value
        private fun skip() { while (text.getOrNull(index) in listOf(' ', '\t', '\r', '\n')) index++ }
    }
}

